-- Every city in Saudi Arabia, not the 110 someone had time to type.
--
-- The hand-seeded list covered the places orders actually go, which is fine until a branch opens
-- somewhere else and the picker cannot name it. All 4,581 cities from the reference dataset are
-- loaded here, each with its official id and centre point, and each named in Arabic and English.
--
-- Cities already linked to an official id in the previous migration are skipped, so the 110 keep
-- their ids and everything pointing at them — client_branches.city_id above all — is untouched.
--
-- The rows arrive with sort_order 500 against the existing 100, so the places already in use stay
-- at the top of a picker that now has thousands of entries behind them.
--
-- Loaded through a temporary table rather than one enormous statement: the names have to be written
-- after the cities exist, and a CTE cannot see rows a sibling CTE is inserting — they share one
-- snapshot. Repeating 4,581 literals twice to work around that would double a file that is already
-- large enough.

CREATE TEMP TABLE _city_import (ext_id integer, region_code text, en text, ar text, lat double precision, lng double precision);

