INSERT INTO qvm_new_apps.cities (region_id, external_id, location_lat, location_lng, sort_order)
SELECT r.region_id, s.ext_id, s.lat, s.lng, 500
FROM _city_import s
JOIN qvm_new_apps.regions r ON r.external_code = s.region_code
WHERE NOT EXISTS (SELECT 1 FROM qvm_new_apps.cities c WHERE c.external_id = s.ext_id);

INSERT INTO qvm_new_apps.cities_descriptions (city_id, language_id, name)
SELECT c.city_id, l.language_id, CASE l.code WHEN 'ar' THEN s.ar ELSE s.en END
FROM _city_import s
JOIN qvm_new_apps.cities c ON c.external_id = s.ext_id
JOIN qvm_new_apps.languages l ON l.code IN ('en', 'ar')
ON CONFLICT (city_id, language_id) DO NOTHING;

DROP TABLE _city_import;
